#!/usr/bin/env python3
"""Payroll summary: python3 payroll.py INPUT_DIR OUTPUT_FILE"""
import csv, gzip, io, json, re, sys
from datetime import datetime, timedelta, timezone, date
from fractions import Fraction
from pathlib import Path
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


def read_text(path):
    data = Path(path).read_bytes()
    if data[:2] == b"\x1f\x8b":
        data = gzip.decompress(data)
    return data.decode("utf-8-sig")


def lines_of(text):
    return [l for l in text.replace("\r\n", "\n").replace("\r", "\n").split("\n") if l.strip() != ""]


def to_epoch(dt):
    return int((dt - EPOCH).total_seconds())


def local_to_epoch(zone, naive, fold=0):
    return to_epoch(naive.replace(tzinfo=zone, fold=fold).astimezone(UTC))


def std_offset(zone, near):
    """Standard (non-DST) UTC offset of zone around the given date."""
    d = datetime(near.year, near.month, near.day, 12, tzinfo=zone)
    return d.utcoffset() - (d.dst() or timedelta(0))


def parse_iso(s):
    s = s.strip()
    if s.endswith("Z") or s.endswith("z"):
        s = s[:-1] + "+00:00"
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=UTC)
    return dt


# ---------------- format readers: yield (id, emp, dir, epoch) ----------------

def read_abbr(text, zone):
    header = None
    for row in csv.reader(io.StringIO("\n".join(lines_of(text)))):
        if not row:
            continue
        cells = [c.strip() for c in row]
        if "Badge" in cells and "Punch" in cells:
            header = {n: i for i, n in enumerate(cells)}
            continue
        if header is None:
            continue
        g = lambda n: cells[header[n]] if n in header and header[n] < len(cells) else ""
        m, d, y = g("Date").split("/")
        t = g("Time").upper()
        ampm = None
        if t.endswith("AM") or t.endswith("PM"):
            ampm = t[-2:]
            t = t[:-2].strip()
        parts = [int(p) for p in t.split(":")]
        while len(parts) < 3:
            parts.append(0)
        h, mi, s = parts
        if ampm:
            h = h % 12 + (12 if ampm == "PM" else 0)
        naive = datetime(int(y), int(m), int(d), h, mi, s)
        fold = 0 if g("Zone").upper().endswith("DT") else 1
        yield g("Record"), g("Badge"), g("Punch").upper(), local_to_epoch(zone, naive, fold)


def read_epoch(text):
    schema = 1
    for l in lines_of(text):
        o = json.loads(l)
        if "schema" in o and "id" not in o and "punch_id" not in o:
            schema = int(o["schema"])
            continue
        if o.get("heartbeat"):
            continue
        if schema == 2:
            pid, emp, d = o["punch_id"], o["employee"], o["direction"]
            ts = int(o["epoch_ms"]) // 1000
        else:
            pid, emp, d = o["id"], o["emp"], o["dir"]
            ts = int(o["ts"]) if "ts" in o else int(o["ts_ms"]) // 1000
        yield str(pid), str(emp).strip(), str(d).upper(), ts


def read_offset(text):
    for r in csv.DictReader(io.StringIO("\n".join(lines_of(text))), delimiter=";"):
        r = {k.strip(): v for k, v in r.items()}
        d = "IN" if r["event"].strip() == "clock_in" else "OUT"
        yield r["punch_id"].strip(), r["employee"].strip(), d, to_epoch(parse_iso(r["timestamp"]))


def read_legacy(text, zone):
    off = None
    for l in lines_of(text):
        t = l[0]
        if t == "H":
            f = l[13:18].strip()
            if re.fullmatch(r"[+-]\d{4}", f):
                sign = -1 if f[0] == "-" else 1
                off = sign * timedelta(hours=int(f[1:3]), minutes=int(f[3:5]))
            else:
                off = None
        elif t == "D":
            ts = datetime.strptime(l[16:30], "%Y%m%d%H%M%S")
            o = off if off is not None else std_offset(zone, ts)
            if off is None:
                # standard offset for that date (zone offset constant per date)
                pass
            epoch = to_epoch(ts.replace(tzinfo=UTC) - o)
            yield l[1:9], "E" + l[9:15].strip(), "IN" if l[15] == "I" else "OUT", epoch


def read_de(text, zone):
    rows = lines_of(text)
    header = None
    for row in csv.reader(rows, delimiter="\t"):
        cells = [c.strip() for c in row]
        if "Ausweis" in cells:
            header = {n: i for i, n in enumerate(cells)}
            continue
        if header is None:
            continue
        g = lambda n: cells[header[n]]
        d, m, y = g("Datum").split(".")
        hh, mm = g("Uhrzeit").split(":")[:2]
        naive = datetime(int(y), int(m), int(d), int(hh), int(mm))
        fold = 0 if g("Zeitzone").upper() == "MESZ" else 1
        yield g("Nr"), g("Ausweis"), "IN" if g("Buchung").upper() == "K" else "OUT", local_to_epoch(zone, naive, fold)


def read_localcsv(text, zone):
    for r in csv.DictReader(io.StringIO("\n".join(lines_of(text)))):
        r = {k.strip(): v.strip() for k, v in r.items()}
        naive = datetime.strptime(r["local_time"], "%Y-%m-%d %H:%M:%S")
        yield r["punch_ref"], r["employee_id"], r["direction"].upper(), local_to_epoch(zone, naive, 0)


def read_localjsonl(text, zone):
    for l in lines_of(text):
        o = json.loads(l)
        p = o.get("punch")
        if not p:
            continue
        pid = p["id"]
        pid = str(int(pid)) if isinstance(pid, (int, float)) else str(pid).strip()
        naive = datetime.strptime(p["at"], "%Y-%m-%d %H:%M:%S")
        yield pid, str(p["badge"]).strip(), str(p["type"]).upper(), local_to_epoch(zone, naive, 0)


def read_site(fmt, text, zone):
    if fmt == "abbr-csv": return read_abbr(text, zone)
    if fmt == "epoch-jsonl": return read_epoch(text)
    if fmt == "offset-csv": return read_offset(text)
    if fmt == "legacy-fixed": return read_legacy(text, zone)
    if fmt == "de-tsv": return read_de(text, zone)
    if fmt == "local-csv": return read_localcsv(text, zone)
    if fmt == "local-jsonl": return read_localjsonl(text, zone)
    raise ValueError("unknown format " + fmt)


def csv_rows(path):
    return [{k.strip(): (v or "").strip() for k, v in r.items() if k}
            for r in csv.DictReader(io.StringIO("\n".join(lines_of(read_text(path)))))]


# ---------------- main ----------------

def main(inp, outp):
    inp = Path(inp)
    period = json.loads(read_text(inp / "period.json"))
    pstart = date.fromisoformat(period["start"])
    pend = date.fromisoformat(period["end"])
    cutoff = parse_iso(period["corrections_cutoff"])
    sites = {r["site"]: (ZoneInfo(r["timezone"]), r["format"]) for r in csv_rows(inp / "sites.csv")}
    emps = csv_rows(inp / "employees.csv")
    home = {e["employee_id"]: sites[e["home_site"]][0] for e in emps if e["home_site"] in sites}

    # 1. collect
    punches = {}  # (site,id) -> [emp, dir, epoch]
    ever = set()
    for site, (zone, fmt) in sites.items():
        d = inp / "exports" / site
        if not d.is_dir():
            continue
        for f in sorted(p for p in d.rglob("*") if p.is_file()):
            for pid, emp, direction, ts in read_site(fmt, read_text(f), zone):
                k = (site, pid)
                ever.add(k)
                if k not in punches:
                    punches[k] = [emp, direction, ts]

    # 2. corrections
    corr = []
    cdir = inp / "corrections"
    if cdir.is_dir():
        for f in sorted(p for p in cdir.rglob("*") if p.is_file()):
            corr.extend(csv_rows(f))
    corr = [c for c in corr if c.get("correction_id")]
    for c in corr:
        c["_t"] = parse_iso(c["issued_at"])
    corr = [c for c in corr if c["_t"] <= cutoff]
    corr.sort(key=lambda c: (c["_t"], c["correction_id"]))
    applied = 0
    voided = set()
    for c in corr:
        k = (c["site"], c["punch_id"])
        a = c["action"].lower()
        if a == "void":
            if k in punches and k not in voided:
                voided.add(k); del punches[k]; applied += 1
        elif a == "set":
            if k in punches:
                punches[k][2] = to_epoch(parse_iso(c["time"])); applied += 1
        elif a == "add":
            if k not in ever:
                ever.add(k)
                punches[k] = [c["employee"], c["type"].upper(), to_epoch(parse_iso(c["time"]))]
                applied += 1
    for k in [k for k, v in punches.items() if v[0] not in home]:
        del punches[k]

    # group by employee
    by_emp = {}
    for (site, pid), (emp, d, ts) in punches.items():
        by_emp.setdefault(emp, []).append((ts, 0 if d == "OUT" else 1, site, pid, d))

    def rnd(site, ts):
        zone = sites[site][0]
        off = int(datetime.fromtimestamp(ts, UTC).astimezone(zone).utcoffset().total_seconds())
        loc = ts + off
        return (loc + 180) // 360 * 360 - off

    def workday(emp, rts):
        return datetime.fromtimestamp(rts, UTC).astimezone(home[emp]).date()

    def in_period(d):
        return pstart <= d <= pend

    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)
    shifts = {e: [] for e in home}

    for emp, lst in by_emp.items():
        lst.sort()
        kept = []
        last = None
        for ts, _, site, pid, d in lst:
            r = rnd(site, ts)
            if last is not None and last[4] == d and ts - last[0] <= 300:
                if in_period(workday(emp, r)):
                    exc["duplicates_dropped"] += 1
                continue
            last = (ts, 0, site, pid, d)
            kept.append((r, site, d))
        openin = None
        for r, site, d in kept:
            if d == "IN":
                if openin is not None and in_period(workday(emp, openin[0])):
                    exc["open_shifts"] += 1
                openin = (r, site)
            else:
                if openin is not None and r - openin[0] <= 16 * 3600:
                    if in_period(workday(emp, openin[0])):
                        shifts[emp].append((openin[0], r, openin[1]))
                    openin = None
                else:
                    if openin is not None:
                        if in_period(workday(emp, openin[0])):
                            exc["open_shifts"] += 1
                        openin = None
                    if in_period(workday(emp, r)):
                        exc["orphan_outs"] += 1
        if openin is not None and in_period(workday(emp, openin[0])):
            exc["open_shifts"] += 1

    # rates
    rates = {}
    for r in csv_rows(inp / "rates.csv"):
        rates.setdefault(r["employee_id"], []).append((date.fromisoformat(r["effective_from"]), Fraction(r["hourly_rate"])))
    for v in rates.values():
        v.sort()

    def night(a, b, zone):
        if b <= a:
            return 0
        d0 = datetime.fromtimestamp(a, UTC).astimezone(zone).date() - timedelta(days=1)
        d1 = datetime.fromtimestamp(b, UTC).astimezone(zone).date()
        tot = 0
        d = d0
        while d <= d1:
            s = local_to_epoch(zone, datetime(d.year, d.month, d.day, 22))
            n = d + timedelta(days=1)
            e = local_to_epoch(zone, datetime(n.year, n.month, n.day, 6))
            lo, hi = max(a, s), min(b, e)
            if hi > lo:
                tot += hi - lo
            d = n
        return tot // 60

    result = {}
    T = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    totgross = 0
    for emp in sorted(home):
        sh = sorted(shifts[emp])
        daily = {}
        weekly = {}
        n = paid_t = ot_t = night_t = 0
        gross = Fraction(0)
        for i, o, site in sh:
            wd = workday(emp, i)
            wk = wd - timedelta(days=wd.weekday())
            worked = max(0, (o - i) // 60)
            paid = worked - 30 if worked > 360 else worked
            nm = min(night(i, o, sites[site][0]), paid)
            before = daily.get(wd, 0)
            daily[wd] = before + paid
            dot = max(0, before + paid - max(before, 480))
            nondaily = paid - dot
            wb = weekly.get(wk, 0)
            weekly[wk] = wb + nondaily
            wot = max(0, wb + nondaily - max(wb, 2400))
            ot = dot + wot
            reg = paid - ot
            rate = Fraction(0)
            for ef, rv in rates.get(emp, []):
                if ef <= wd:
                    rate = rv
            gross += rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * nm / 60
            n += 1; paid_t += paid; ot_t += ot; night_t += nm
        cents = int((gross * 100 + Fraction(1, 2)) // 1)
        g = "%d.%02d" % divmod(cents, 100)
        totgross += cents
        result[emp] = dict(shifts=n, paid_minutes=paid_t, overtime_minutes=ot_t, night_minutes=night_t, gross=g)
        T["shifts"] += n; T["paid_minutes"] += paid_t; T["overtime_minutes"] += ot_t; T["night_minutes"] += night_t
    T["gross"] = "%d.%02d" % divmod(totgross, 100)
    out = dict(period=dict(start=period["start"], end=period["end"]), employees=result, exceptions=exc, totals=T)
    Path(outp).parent.mkdir(parents=True, exist_ok=True)
    Path(outp).write_text(json.dumps(out, indent=1))


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
